function policy(obs, params, mem) {
  var torso = obs[0], spin = obs[1];
  var hA = obs[5], sA = obs[6], kA = obs[7], skA = obs[8], fA = obs[9] > 0.5 ? 1 : 0;
  var hB = obs[10], sB = obs[11], kB = obs[12], skB = obs[13], fB = obs[14] > 0.5 ? 1 : 0;
  var a1 = obs[15], a2 = obs[16], a3 = obs[17], a4 = obs[18], tt = obs[19];
  var P = params;

  var freq = P[0], hipAmp = P[1], hipBias = P[2], hipPh = P[3], duty = P[4];
  var kStr = P[5], kSw = P[6], kpH = P[7], kdH = P[8], kpK = P[9], kdK = P[10];
  var kpB = P[11], kdBal = P[12], thRef = P[13], pushOff = P[14];
  var hKnee = P[15], hHip = P[16], kpPLL = P[17];

  if (mem.ph === undefined) { mem.ph = 0; mem.cA = fA; mem.cB = fB; }
  mem.ph += freq * 0.016666666666666666;

  if (fA && !mem.cA) {
    var e = mem.ph + hipPh; e -= Math.floor(e);
    if (e > 0.5) e -= 1;
    mem.ph -= kpPLL * e;
  }
  if (fB && !mem.cB) {
    var e2 = mem.ph + 0.5 + hipPh; e2 -= Math.floor(e2);
    if (e2 > 0.5) e2 -= 1;
    mem.ph -= kpPLL * e2;
  }
  mem.cA = fA; mem.cB = fB;
  mem.ph -= Math.floor(mem.ph);

  var ob = a1;
  var t2 = 0.6 * a2; if (t2 > ob) ob = t2;
  var t3 = 0.28 * a3; if (t3 > ob) ob = t3;
  var t4 = 0.12 * a4; if (t4 > ob) ob = t4;
  var lift = (ob - 0.05) * 3.2;
  if (lift < 0) lift = 0; else if (lift > 1) lift = 1;

  var ramp = tt < 0.2 ? tt * 5 : 1;
  var errT = torso - thRef * ramp;
  var danger = (errT < 0 ? -errT : errT) - 0.26;
  if (danger > 0) { danger *= 2.4; if (danger > 1) danger = 1; } else danger = 0;

  var out = [0, 0, 0, 0];
  for (var leg = 0; leg < 2; leg++) {
    var q = mem.ph + (leg ? 0.5 : 0) + hipPh;
    q -= Math.floor(q);
    var angH = leg ? hB : hA, spdH = leg ? sB : sA;
    var angK = leg ? kB : kA, spdK = leg ? skB : skA;
    var fc = leg ? fB : fA;

    var c = Math.cos(6.283185307179586 * q);
    var ht = hipBias + hipAmp * ramp * (1 - 0.5 * danger) * c;
    if (lift > 0) {
      var hw = q - 0.55;
      if (hw > 0) { hw *= 2.2222222222; if (hw > 1) hw = 1; ht += hHip * lift * hw; }
    }
    ht += (kpB * errT + kdBal * spin) * (1 + 1.6 * danger);
    if (ht > 1.18) ht = 1.18; else if (ht < -0.88) ht = -0.88;
    var uH = kpH * (ht - angH) - kdH * spdH;

    var bend = 0;
    if (q >= duty) {
      var s = (q - duty) / (1 - duty);
      if (s > 1) s = 1;
      bend = Math.sin(3.141592653589793 * Math.pow(s, 0.62)) * ramp;
      if (bend < 0) bend = 0;
      if (fc) bend *= 0.3;
    }
    var kb = kSw - hKnee * lift;
    if (kb < -1.66) kb = -1.66;
    var kt = kStr + (kb - kStr) * bend;
    if (kt > -0.06) kt = -0.06; else if (kt < -1.66) kt = -1.66;
    var uK = kpK * (kt - angK) - kdK * spdK;
    if (q > duty - 0.22 && q < duty) {
      var w = Math.sin(3.141592653589793 * (q - (duty - 0.22)) / 0.22);
      uK += pushOff * w * (fc ? 1 : 0.25) * ramp;
    }

    if (uH > 1) uH = 1; else if (uH < -1) uH = -1;
    if (uK > 1) uK = 1; else if (uK < -1) uK = -1;
    out[leg * 2] = uH;
    out[leg * 2 + 1] = uK;
  }
  return out;
}

function learn(lab) {
  var D = 18;
  var LO = [0.85, 0.50, -0.35, -0.50, 0.38, -0.36, -1.62, 0.20, 0.02, 0.20, 0.02, -1.50, -0.80, -0.32, 0.00, 0.00, 0.00, 0.00];
  var HI = [1.80, 1.20, 0.50, 0.50, 0.66, -0.06, -0.60, 2.60, 0.45, 2.60, 0.45, 1.50, 0.80, 0.15, 1.00, 1.50, 1.30, 0.70];
  var NOM = [1.05, 0.85, 0.12, 0.00, 0.50, -0.16, -1.15, 1.00, 0.12, 1.20, 0.10, 0.70, 0.35, -0.10, 0.35, 0.50, 0.40, 0.15];

  var used = 0, bestScore = -1e30, bestP = NOM.slice();
  var cache = {};

  var budget = 950;
  try {
    if (typeof lab.trials === 'number' && lab.trials > 10) budget = Math.min(950, Math.floor(lab.trials) - 3);
  } catch (e) { }
  if (budget > 950) budget = 950;
  if (budget < 30) budget = 30;

  function evaluate(p) {
    var i;
    for (i = 0; i < D; i++) {
      if (p[i] < LO[i]) p[i] = LO[i];
      else if (p[i] > HI[i]) p[i] = HI[i];
    }
    var key = '';
    for (i = 0; i < D; i++) key += p[i].toFixed(4) + ',';
    if (cache[key]) return cache[key];

    var r = null;
    try { r = lab.trial(p.slice()); } catch (e) { r = null; }
    used++;

    var d = 0, tm = 0, oc = 'error', sc = -1e5;
    if (r && typeof r.distance === 'number' && isFinite(r.distance)) {
      d = r.distance;
      if (typeof r.time === 'number' && isFinite(r.time)) tm = r.time;
      if (typeof r.outcome === 'string') oc = r.outcome;
      if (oc === 'invalid' || oc === 'error') sc = -1e5;
      else {
        var sm = (tm - 8) * 0.5;
        if (sm < 0) sm = 0; else if (sm > 1) sm = 1;
        sc = d > 0 ? d * (1 + 0.55 * sm * sm * (3 - 2 * sm)) : d;
      }
    }
    var res = { s: sc, d: d, t: tm, o: oc, p: p.slice() };
    cache[key] = res;
    if (sc > bestScore) { bestScore = sc; bestP = p.slice(); }
    return res;
  }

  function gauss() {
    var u = Math.random(), v = Math.random();
    return Math.sqrt(-2 * Math.log(u + 1e-9)) * Math.cos(6.283185307179586 * v);
  }

  var i, j, k, gen;

  /* ---- phase 1: nominal + mixed wide exploration ---- */
  evaluate(NOM.slice());
  for (i = 0; i < 159 && used < budget; i++) {
    var p1 = new Array(D);
    for (j = 0; j < D; j++) {
      if (Math.random() < 0.42) p1[j] = LO[j] + Math.random() * (HI[j] - LO[j]);
      else p1[j] = NOM[j] + 0.24 * (HI[j] - LO[j]) * gauss();
    }
    evaluate(p1);
  }

  /* ---- phase 2: cross-entropy search ---- */
  var mean = bestP.slice();
  var sig = new Array(D);
  for (i = 0; i < D; i++) sig[i] = 0.17 * (HI[i] - LO[i]);

  for (gen = 0; gen < 10 && used < budget; gen++) {
    var lam = 50;
    var pop = [];
    for (k = 0; k < lam && used < budget; k++) {
      var q2 = new Array(D);
      for (j = 0; j < D; j++) {
        var x = mean[j] + sig[j] * gauss();
        for (var g2 = 0; g2 < 8; g2++) {
          if (x < LO[j]) x = LO[j] + (LO[j] - x) * 0.5;
          else if (x > HI[j]) x = HI[j] - (x - HI[j]) * 0.5;
          else break;
        }
        if (x < LO[j]) x = LO[j];
        if (x > HI[j]) x = HI[j];
        q2[j] = x;
      }
      pop.push(evaluate(q2));
    }
    if (pop.length === 0) break;
    pop.sort(function (a, b) { return b.s - a.s; });
    var elite = pop.slice(0, Math.min(10, pop.length));
    var nm = new Array(D), ns = new Array(D);
    for (j = 0; j < D; j++) {
      var m = 0, wsum = 0, w, e3;
      for (e3 = 0; e3 < elite.length; e3++) {
        w = Math.log(elite.length + 0.6) - Math.log(e3 + 1);
        m += w * elite[e3].p[j]; wsum += w;
      }
      m /= wsum;
      var v = 0;
      for (e3 = 0; e3 < elite.length; e3++) {
        w = Math.log(elite.length + 0.6) - Math.log(e3 + 1);
        var dd = elite[e3].p[j] - m;
        v += w * dd * dd;
      }
      v /= wsum;
      nm[j] = m;
      var s2 = Math.sqrt(v) * 0.88 + 0.005 * (HI[j] - LO[j]);
      var fl = 0.008 * (HI[j] - LO[j]);
      if (s2 < fl) s2 = fl;
      ns[j] = s2;
    }
    mean = nm; sig = ns;
  }

  /* ---- phase 3: coordinate pattern search around best ---- */
  var step = new Array(D);
  for (i = 0; i < D; i++) step[i] = 0.06 * (HI[i] - LO[i]);
  for (var it = 0; it < 90 && used < budget; it++) {
    var improved = false;
    for (i = 0; i < D && used < budget; i++) {
      for (var sgn = 1; sgn >= -1; sgn -= 2) {
        if (used >= budget) break;
        var p3 = bestP.slice();
        p3[i] += sgn * step[i];
        var r3 = evaluate(p3);
        if (r3.s >= bestScore - 1e-12) { improved = true; step[i] *= 1.22; }
      }
    }
    if (improved) {
      for (i = 0; i < D; i++) step[i] *= 0.95;
    } else {
      var any = false;
      for (i = 0; i < D; i++) { step[i] *= 0.55; if (step[i] > 1e-5) any = true; }
      if (!any) break;
    }
  }

  return bestP.slice();
}

function policy(obs, params, mem) {
  var th = obs[0], om = obs[1], vx = obs[2], vy = obs[3], ycen = obs[4];
  var hA = obs[5], hsA = obs[6], kA = obs[7], ksA = obs[8], fA = obs[9] > 0.5 ? 1 : 0;
  var hB = obs[10], hsB = obs[11], kB = obs[12], ksB = obs[13], fB = obs[14] > 0.5 ? 1 : 0;
  var a1 = obs[15], a2 = obs[16], a3 = obs[17], a4 = obs[18], tt = obs[19];

  var P = params;
  if (!P || P.length < 23) {
    P = [1.15, 0.30, 0.10, 0.58, -0.12, -1.15, 0.90, 1.10, 0.17, 0.07, 1.10, 0.35, -0.08, 0.90, 0.25, 0.30, 0.755, 0.80, 0.30, 0.55, 0.30, 0.80, 1];
  }

  var fq = P[0], amp = P[1], bias = P[2], duty = P[3];
  var kStd = P[4], kSwg = P[5];
  var kpH = P[6], kpK = P[7], dH = P[8], dK = P[9];
  var kpT = P[10], kdT = P[11], thR = P[12];
  var kpS = P[13], kdS = P[14], push = P[15];
  var yDes = P[16], kpY = P[17], kdY = P[18];
  var liftG = P[19], pllG = P[20], shp = P[21];
  var dirn = P[22] >= 0 ? 1 : -1;

  if (duty < 0.25) duty = 0.25; else if (duty > 0.82) duty = 0.82;
  if (fq < 0.25) fq = 0.25; else if (fq > 3.5) fq = 3.5;
  if (shp < 0.3) shp = 0.3; else if (shp > 1.8) shp = 1.8;

  var kdH = dH * Math.sqrt(kpH > 0.0001 ? kpH : 0.0001);
  var kdK = dK * Math.sqrt(kpK > 0.0001 ? kpK : 0.0001);

  if (mem.ph === undefined) {
    mem.ph = 0.08;
    mem.pA = fA;
    mem.pB = fB;
  }

  var ramp = tt >= 0.8 ? 1 : (tt <= 0 ? 0 : tt * 1.25);

  mem.ph += fq * 0.016666666666666666;
  if (fA && !mem.pA) {
    var e1 = mem.ph - Math.round(mem.ph);
    mem.ph -= pllG * e1;
  }
  if (fB && !mem.pB) {
    var t2 = mem.ph - 0.5;
    var e2 = t2 - Math.round(t2);
    mem.ph -= pllG * e2;
  }
  mem.pA = fA;
  mem.pB = fB;
  if (mem.ph < 0) mem.ph += 1; else if (mem.ph >= 1) mem.ph -= 1;

  var aw = a1 + 0.75 * a2 + 0.35 * a3 + 0.12 * a4;
  if (aw > 1.2) aw = 1.2; else if (aw < -0.8) aw = -0.8;
  var lift = aw * liftG;

  var hipH = ycen - 0.31;

  var hF = dirn * ramp * (bias + amp);
  var hBk = dirn * ramp * (bias - amp);
  var kSt = -0.05 + ramp * (kStd + 0.05);
  var kSw = -0.05 + ramp * (kSwg + 0.05);

  var H = [hA, hB], HV = [hsA, hsB], K = [kA, kB], KV = [ksA, ksB];
  var FC = [fA, fB], OF = [0, 0.5];
  var out = [0, 0, 0, 0];

  for (var i = 0; i < 2; i++) {
    var q = mem.ph + OF[i];
    q -= Math.floor(q);

    var mode = q >= duty ? 0 : (FC[i] ? 1 : 2);
    var hT, kT, pushT = 0, s, sm, bend;

    if (mode === 0) {
      s = (q - duty) / (1 - duty);
      if (s > 1) s = 1; else if (s < 0) s = 0;
      sm = s * s * (3 - 2 * s);
      hT = hBk + (hF - hBk) * sm;
      hT -= dirn * (kpS * (th - thR) + kdS * om);
      bend = Math.sin(3.141592653589793 * Math.pow(s, shp));
      if (bend < 0) bend = 0;
      kT = kSt + (kSw - kSt) * bend;
      if (lift > 0) kT -= lift * 2.2 * bend;
    } else if (mode === 1) {
      s = q / duty;
      if (s > 1) s = 1;
      hT = hF + (hBk - hF) * s;
      kT = kSt;
      if (q > duty - 0.30) {
        pushT = push * Math.sin(3.141592653589793 * (q - duty + 0.30) / 0.30);
      }
    } else {
      hT = hF;
      hT -= dirn * (kpS * (th - thR) + kdS * om);
      kT = kSt;
    }

    if (hT > 1.17) hT = 1.17; else if (hT < -0.87) hT = -0.87;
    if (kT > -0.055) kT = -0.055; else if (kT < -1.67) kT = -1.67;

    var uH, uK, eY;
    if (mode === 1) {
      uH = kpH * (hT - H[i]) - kdH * HV[i] + dirn * (kpT * (th - thR) + kdT * om);
      eY = yDes - hipH;
      uK = kpK * (kT - K[i]) - kdK * KV[i] + kpY * eY - kdY * vy + pushT;
    } else if (mode === 2) {
      uH = kpH * (hT - H[i]) - kdH * HV[i];
      eY = yDes - hipH;
      if (eY < 0) eY = 0;
      uK = kpK * (kT - K[i]) - kdK * KV[i] + kpY * eY - kdY * (vy < 0 ? vy : 0);
    } else {
      uH = kpH * (hT - H[i]) - kdH * HV[i];
      uK = kpK * (kT - K[i]) - kdK * KV[i];
    }

    if (uH > 1) uH = 1; else if (uH < -1) uH = -1;
    if (uK > 1) uK = 1; else if (uK < -1) uK = -1;
    out[i * 2] = uH;
    out[i * 2 + 1] = uK;
  }
  return out;
}

function learn(lab) {
  var D = 23, DIRI = 22;
  var LO = [0.70, 0.06, -0.35, 0.35, -0.85, -1.66, 0.15, 0.15, 0.02, 0.01, -5.0, -1.8, -0.50, -3.0, -1.5, -1.2, 0.50, -4.0, -2.0, -1.5, 0.00, 0.30, -1];
  var HI = [2.60, 0.85, 0.60, 0.78, -0.05, -0.55, 3.00, 3.50, 0.55, 0.35, 5.0, 1.8, 0.35, 3.0, 1.5, 1.5, 0.80, 4.0, 2.0, 2.5, 0.80, 1.80, 1];
  var NOM = [1.15, 0.30, 0.10, 0.58, -0.12, -1.15, 0.90, 1.10, 0.17, 0.07, 1.10, 0.35, -0.08, 0.90, 0.25, 0.30, 0.755, 0.80, 0.30, 0.55, 0.30, 0.80, 1];

  var budget = 985;
  try {
    if (typeof lab.trialsLeft === 'function') {
      var tl = lab.trialsLeft();
      if (typeof tl === 'number' && isFinite(tl) && tl > 0) budget = Math.min(985, Math.floor(tl) - 5);
    }
    if (typeof lab.trials === 'number' && isFinite(lab.trials) && lab.trials > 0) {
      budget = Math.min(budget, Math.floor(lab.trials) - 5);
    }
  } catch (e) { }
  if (budget > 985) budget = 985;
  if (budget < 30) budget = 30;

  var used = 0, bestS = -1e30, bestP = NOM.slice();
  var cache = {};

  function clip(p) {
    for (var i = 0; i < D; i++) {
      if (i === DIRI) { p[i] = p[i] >= 0 ? 1 : -1; }
      else {
        if (p[i] < LO[i]) p[i] = LO[i];
        else if (p[i] > HI[i]) p[i] = HI[i];
      }
    }
    return p;
  }
  function keyOf(p) {
    var s = '', i;
    for (i = 0; i < D; i++) s += p[i].toFixed(3) + ',';
    return s;
  }
  function evaluate(p) {
    clip(p);
    var k = keyOf(p);
    if (cache[k]) return cache[k];
    var res;
    if (used >= budget) {
      res = { s: -1e30, d: 0, t: 0, o: 'none', p: p.slice() };
      cache[k] = res;
      return res;
    }
    var r = null;
    try { r = lab.trial(p.slice()); } catch (e) { r = null; }
    used++;
    var d = 0, tm = 0, oc = 'error';
    if (r) {
      if (typeof r.distance === 'number' && isFinite(r.distance)) d = r.distance;
      if (typeof r.time === 'number' && isFinite(r.time)) tm = r.time;
      if (typeof r.outcome === 'string') oc = r.outcome;
    }
    var sc;
    if (oc === 'invalid' || oc === 'error') sc = -1e6;
    else {
      sc = d + 0.15 * tm;
      if (oc === 'finished') sc += 1.5;
      if (d < 0.4) sc -= 2.0;
    }
    res = { s: sc, d: d, t: tm, o: oc, p: p.slice() };
    cache[k] = res;
    if (sc > bestS) { bestS = sc; bestP = p.slice(); }
    return res;
  }
  function gauss() {
    var u = Math.random(), v = Math.random();
    return Math.sqrt(-2 * Math.log(u + 1e-12)) * Math.cos(6.283185307179586 * v);
  }

  var i, j, k, g;

  try {
    /* ---- phase 0: structural sign scan ---- */
    for (var dv = 1; dv >= -1; dv -= 2) {
      for (var bv = 1; bv >= -1; bv -= 2) {
        for (var sv = 1; sv >= -1; sv -= 2) {
          for (var yv = 1; yv >= -1; yv -= 2) {
            if (used >= budget) break;
            var p0 = NOM.slice();
            p0[DIRI] = dv;
            p0[10] = NOM[10] * bv; p0[11] = NOM[11] * bv;
            p0[13] = NOM[13] * sv; p0[14] = NOM[14] * sv;
            p0[17] = NOM[17] * yv; p0[18] = NOM[18] * yv;
            evaluate(p0);
          }
        }
      }
    }

    var base = bestP.slice();

    /* ---- phase 1: exploration ---- */
    for (i = 0; i < 50 && used < budget; i++) {
      var pu = new Array(D);
      for (j = 0; j < D; j++) {
        pu[j] = (j === DIRI) ? base[DIRI] : LO[j] + Math.random() * (HI[j] - LO[j]);
      }
      evaluate(pu);
    }
    for (i = 0; i < 70 && used < budget; i++) {
      var pg = new Array(D);
      for (j = 0; j < D; j++) {
        if (j === DIRI) { pg[j] = base[DIRI]; continue; }
        var xg = base[j] + 0.22 * (HI[j] - LO[j]) * gauss();
        if (xg < LO[j]) xg = LO[j]; else if (xg > HI[j]) xg = HI[j];
        pg[j] = xg;
      }
      evaluate(pg);
    }

    /* ---- phase 2: cross-entropy search ---- */
    var mean = bestP.slice();
    var sig = new Array(D);
    for (i = 0; i < D; i++) sig[i] = (i === DIRI) ? 0.001 : 0.13 * (HI[i] - LO[i]);
    var lam = 46, eliteN = 9;
    for (g = 0; g < 16; g++) {
      if (used + lam > budget - 110) break;
      var pop = [];
      for (k = 0; k < lam; k++) {
        var q = new Array(D);
        for (j = 0; j < D; j++) {
          if (j === DIRI) { q[j] = mean[DIRI]; continue; }
          var x2 = mean[j] + sig[j] * gauss();
          if (x2 < LO[j]) x2 = LO[j]; else if (x2 > HI[j]) x2 = HI[j];
          q[j] = x2;
        }
        pop.push(evaluate(q));
      }
      pop.sort(function (a, b) { return b.s - a.s; });
      var nm = new Array(D), ns = new Array(D);
      for (j = 0; j < D; j++) {
        if (j === DIRI) { nm[j] = mean[DIRI]; ns[j] = 0.001; continue; }
        var w, wsum = 0, m = 0, v = 0, e;
        for (e = 0; e < eliteN; e++) {
          w = Math.log(eliteN + 0.6) - Math.log(e + 1);
          m += w * pop[e].p[j]; wsum += w;
        }
        m /= wsum;
        for (e = 0; e < eliteN; e++) {
          w = Math.log(eliteN + 0.6) - Math.log(e + 1);
          var dd = pop[e].p[j] - m;
          v += w * dd * dd;
        }
