  var hipB=num(obs[10],0.0), hipBs=num(obs[11],0.0), kneeB=num(obs[12],-0.1), kneeBs=num(obs[13],0.0);
  var a1=num(obs[15],0.0), a2=num(obs[16],0.0), a3=num(obs[17],0.0), a4=num(obs[18],0.0);
