  r=Math.max(r,(-vy-num(cfg.vyT,3.5))/Math.max(0.5,num(cfg.vyS,4.0)));
  r=Math.max(r,(Math.abs(vx)-num(cfg.vxT,2.5))/Math.max(0.1,num(cfg.vxS,1.5)));
  r=Math.max(r,(obsSig-num(cfg.oT,0.20))/Math.max(0.02,num(cfg.oS,0.20)));
  var target=Math.max(num(cfg.baseW,0.0),Math.min(1.0,r*Math.max(0.0,num(cfg.gain,1.0))));
  var tw=clampv((t-num(cfg.T,8.0))/Math.max(0.05,num(cfg.TD,0.5)),0.0,1.0);
  if(tw>target) target=tw;
  if(target>mem.adW) mem.adW=Math.min(target,mem.adW+Math.max(0.1,num(cfg.rateUp,4.0))*dt);
  else mem.adW=Math.max(target,mem.adW-Math.max(0.01,num(cfg.rateDown,0.3))*dt);
  mem.adW=clampv(mem.adW,0.0,1.0);
  var sev=0.0;
  sev=Math.max(sev,(num(cfg.eH,0.38)-height)/0.14);
  sev=Math.max(sev,(Math.abs(beta)-num(cfg.eB,1.1))/0.35);
  sev=Math.max(sev,(Math.abs(spin)-num(cfg.eS,16.0))/16.0);
  sev=Math.max(sev,(Math.abs(vy)-6.0)/4.0);
  if(sev>0.0) mem.adEmgUntil=t+Math.max(0.1,num(cfg.eDur,0.8));
  var et=(t<mem.adEmgUntil)?1.0:0.0;
  mem.adEmg+= (et-mem.adEmg)*Math.min(1.0,dt*14.0);
  if(sev>0.8 && mem.adEmg<0.35) mem.adEmg=0.35;
  var fast=oldCore(obs,pf,mem);
  var out=fast;
  if(mem.adW>0.001 || et>0.0){
    if(!mem.adSlow){ mem.adSlow={}; mem.adSlowOn=0; }
    if(!mem.adSlowOn){ copyOldMem(mem.adSlow,mem); mem.adSlowOn=1; }
    var slow=oldCore(obs,ps,mem.adSlow);
    var w=mem.adW;
    out=[
      fast[0]*(1.0-w)+slow[0]*w,
      fast[1]*(1.0-w)+slow[1]*w,
      fast[2]*(1.0-w)+slow[2]*w,
