function updateMetrics(o,out){
  if(!G_REC) return;
  var beta=num(o[0],0.0),spin=num(o[1],0.0),vx=num(o[2],0.0),vy=num(o[3],0.0),height=num(o[4],0.0);
  var hipAs=num(o[6],0.0),kneeAs=num(o[8],0.0),hipBs=num(o[11],0.0),kneeBs=num(o[13],0.0),t=num(o[19],0.0);
  G_REC.calls++;
  G_REC.lastBeta=beta; G_REC.lastSpin=spin; G_REC.lastVx=vx; G_REC.lastVy=vy; G_REC.lastHeight=height; G_REC.lastT=t;
  if(height<G_REC.minH) G_REC.minH=height;
  if(height>G_REC.maxH) G_REC.maxH=height;
  if(Math.abs(beta)>G_REC.maxAbsBeta) G_REC.maxAbsBeta=Math.abs(beta);
  if(Math.abs(spin)>G_REC.maxAbsSpin) G_REC.maxAbsSpin=Math.abs(spin);
  if(Math.abs(vy)>G_REC.maxAbsVy) G_REC.maxAbsVy=Math.abs(vy);
  var js=Math.max(Math.abs(hipAs),Math.abs(kneeAs),Math.abs(hipBs),Math.abs(kneeBs));
