  if(t>8.0){
    if(height<G_REC.minH8) G_REC.minH8=height;
    if(Math.abs(beta)>G_REC.maxAbsBeta8) G_REC.maxAbsBeta8=Math.abs(beta);
    if(Math.abs(spin)>G_REC.maxAbsSpin8) G_REC.maxAbsSpin8=Math.abs(spin);
  }
  if(t>9.0){
    if(height<G_REC.minH9) G_REC.minH9=height;
    if(Math.abs(beta)>G_REC.maxAbsBeta9) G_REC.maxAbsBeta9=Math.abs(beta);
    if(Math.abs(spin)>G_REC.maxAbsSpin9) G_REC.maxAbsSpin9=Math.abs(spin);
    G_REC.sumVx9+=vx; G_REC.count9++;
  }
