}
function policy(obs,params,mem){
  mem=mem||{};
  var out=null;
  if(params && typeof params.length==="number"){
    out=oldCore(obs,params,mem);
  }else if(params && typeof params==="object"){
    var mode=params.mode|0;
    if(mode===0){
      out=oldCore(obs,params.p||PREV,mem);
    }else if(mode===2){
      out=standCore(obs,params.p||params.s||S_DEF);
    }else if(mode===6){
      out=adaptivePolicy(obs,params,mem);
    }else{
      out=oldCore(obs,params.p||PREV,mem);
    }
  }else{
    out=oldCore(obs,PREV,mem);
  }
  updateMetrics(obs,out);
  return out;
}

function learn(lab){
  var startTime=(typeof Date!=="undefined" && Date.now)?Date.now():0;
  function timeUp(){ return startTime && ((Date.now()-startTime)>148000); }
  var MAX_TRIALS=994;
  var evals=0;
  var allRecs=[];
  var CFG_DEF={T:8.0,TD:0.5,gain:1.0,baseW:0.0,bT:0.75,bS:0.35,sT:10.0,sS:8.0,hT:0.55,hS:0.20,vyT:3.5,vyS:4.0,vxT:2.5,vxS:1.5,oT:0.20,oS:0.20,rateUp:4.0,rateDown:0.3,eH:0.38,eB:1.1,eS:16.0,eDur:0.8};
  function vecToCfg(v){
    return {T:v[0],TD:v[1],gain:v[2],baseW:v[3],bT:v[4],bS:v[5],sT:v[6],sS:v[7],hT:v[8],hS:v[9],vyT:v[10],vyS:v[11],vxT:v[12],vxS:v[13],oT:v[14],oS:v[15],rateUp:v[16],rateDown:v[17],eH:v[18],eB:v[19],eS:v[20],eDur:v[21]};
  }
  function cfgToVec(c){
    return [c.T,c.TD,c.gain,c.baseW,c.bT,c.bS,c.sT,c.sS,c.hT,c.hS,c.vyT,c.vyS,c.vxT,c.vxS,c.oT,c.oS,c.rateUp,c.rateDown,c.eH,c.eB,c.eS,c.eDur];
  }
  function makeOld(p){ return {mode:0,p:p.slice()}; }
  function makeStand(p){ return {mode:2,p:p.slice()}; }
  function makeAdaptive(pf,ps,cfg,s){ return {mode:6,pFast:pf.slice(),pSlow:ps.slice(),cfg:cfg,s:(s||S_P5).slice()}; }
  function resetMetrics(){
    G_REC={calls:0,lastBeta:0.0,lastSpin:0.0,lastVx:0.0,lastVy:0.0,lastHeight:0.0,lastT:0.0,
      minH:9.0,maxH:0.0,maxAbsBeta:0.0,maxAbsSpin:0.0,maxAbsVy:0.0,maxJointSpeed:0.0,maxFootSpeed:0.0,sumAbs:0.0,
      minH8:9.0,maxAbsBeta8:0.0,maxAbsSpin8:0.0,
      minH9:9.0,maxAbsBeta9:0.0,maxAbsSpin9:0.0,sumVx9:0.0,count9:0,
      minH95:9.0,maxAbsBeta95:0.0,maxAbsSpin95:0.0,sumVx95:0.0,count95:0};
  }
  function randn(){
    var u=0.0,v=0.0;
    while(u===0.0) u=Math.random();
    while(v===0.0) v=Math.random();
    return Math.sqrt(-2.0*Math.log(u))*Math.cos(2.0*Math.PI*v);
  }
  function scoreTrial(r,met){
    if(!r) return -1e9;
    var out=r.outcome;
    if(out==="invalid"||out==="error") return -1e9;
    var d=num(r.distance,0.0),tm=num(r.time,0.0);
    var sc=12.0*d+2.0*tm;
    if(out==="finished") sc+=25.0; else sc-=20.0*(10.0-tm);
    if(met){
      var v9=(met.count9>0)?met.sumVx9/met.count9:met.lastVx;
      var v95=(met.count95>0)?met.sumVx95/met.count95:v9;
      var h95=(met.count95>0)?met.minH95:met.lastHeight;
      var ab95=(met.count95>0)?met.maxAbsBeta95:Math.abs(met.lastBeta);
      var sp95=(met.count95>0)?met.maxAbsSpin95:Math.abs(met.lastSpin);
      sc+=15.0*clamp(v95,-0.5,2.5);
      sc+=18.0*clamp((h95-0.40)/0.40,0.0,1.0);
      sc-=32.0*Math.max(0.0,0.45-h95)/0.45;
      sc-=22.0*Math.max(0.0,ab95-0.60);
      sc-=3.0*Math.max(0.0,sp95-8.0);
      sc-=20.0*Math.max(0.0,0.55-met.lastHeight)/0.55;
      if(met.minH<0.25) sc-=20.0;
      if(met.maxFootSpeed>24.0) sc-=1e6;
      if(met.maxAbsSpin>58.0) sc-=1e6;
      if(met.maxH>2.10) sc-=1e6;
    }
    return sc;
  }
  function qualityRec(rec){
    if(!rec || rec.outcome==="invalid" || rec.outcome==="error") return -1e9;
    var tm=rec.time,out=rec.outcome,met=rec.met;
    if(out!=="finished"||tm<9.8) return -1e9;
    if(!met) return -1e9;
    if(met.maxFootSpeed>24.0||met.maxAbsSpin>58.0||met.maxH>2.10) return -1e9;
    var h95=(met.count95>0)?met.minH95:met.lastHeight;
    var ab95=(met.count95>0)?met.maxAbsBeta95:Math.abs(met.lastBeta);
    var sp95=(met.count95>0)?met.maxAbsSpin95:Math.abs(met.lastSpin);
    var v95=(met.count95>0)?met.sumVx95/met.count95:met.lastVx;
    if(h95<0.38||ab95>0.95||sp95>13.0||met.lastHeight<0.48) return -1e9;
    var pred=rec.dist+10.0*clamp(v95,-0.5,2.5);
    pred+=2.0*clamp((h95-0.45)/0.40,0.0,1.0);
    pred-=5.0*Math.max(0.0,0.55-h95)/0.55;
    pred-=3.0*Math.max(0.0,ab95-0.70);
    if(rec.sol && rec.sol.cfg && rec.sol.cfg.T>9.3) pred-=0.3;
    return pred;
  }
  function evaluate(sol,tag){
    if(evals>=MAX_TRIALS) return null;
    if(timeUp()) return null;
    if(lab.trialsLeft && lab.trialsLeft()<=0) return null;
    resetMetrics();
    var r;
    try{ r=lab.trial(sol); }
    catch(e){ r={outcome:"error",distance:0.0,time:0.0,energy:0.0}; }
    var met=G_REC;
    evals++;
    var d=num(r.distance,0.0),tm=num(r.time,0.0);
    var rec={sol:sol,dist:d,time:tm,outcome:r.outcome,met:met,score:0.0,quality:0.0,tag:tag};
    rec.score=scoreTrial(r,met);
