  }
  function toU(p,LO,HI){
    var n=LO.length,u=new Array(n);
    for(var i=0;i<n;i++){
      var x=(p[i]-LO[i])/(HI[i]-LO[i]);
      if(!isFinite(x)) x=0.5;
      u[i]=clampv(x,0.0,1.0);
    }
    return u;
  }
  function fromU(u,LO,HI){
    var n=LO.length,p=new Array(n);
    for(var i=0;i<n;i++) p[i]=LO[i]+clampv(u[i],0.0,1.0)*(HI[i]-LO[i]);
    return p;
  }
  function cemRun(N,LO,HI,seed,sigma0,budget,lambda,elite,makeSol,tag){
    var meanU=toU(seed,LO,HI);
    var sigma=new Array(N);
    for(var i0=0;i0<N;i0++) sigma[i0]=sigma0;
    var used=0,gen=0,best=null,stagnant=0;
    while(used<budget && evals<MAX_TRIALS && !timeUp()){
      var pop=[];
      for(var n=0;n<lambda && used<budget && evals<MAX_TRIALS && !timeUp();n++){
        var u=new Array(N);
        if(n===0){ for(var ia=0;ia<N;ia++) u[ia]=meanU[ia]; }
        else{
          for(var ib=0;ib<N;ib++){
            var val=meanU[ib]+sigma[ib]*randn();
            if(Math.random()<0.008) val=Math.random();
            u[ib]=clampv(val,0.0,1.0);
          }
        }
        var pp=fromU(u,LO,HI);
        var rec=evaluate(makeSol(pp),tag);
        used++;
        if(rec) pop.push({u:u,rec:rec});
      }
      if(pop.length===0) break;
      pop.sort(function(a,b){ return b.rec.score-a.rec.score; });
      if(!best || pop[0].rec.score>best.score){ best=pop[0].rec; stagnant=0; } else stagnant++;
      var mu=Math.min(elite,pop.length);
      var w=new Array(mu),wsum=0.0;
      for(var k=0;k<mu;k++){ w[k]=Math.log(mu+0.5)-Math.log(k+1.0); wsum+=w[k]; }
      var newMean=new Array(N),newSigma=new Array(N);
      for(var i1=0;i1<N;i1++) newMean[i1]=0.0;
      for(var k1=0;k1<mu;k1++){ for(var i2=0;i2<N;i2++) newMean[i2]+=w[k1]*pop[k1].u[i2]; }
      for(var i3=0;i3<N;i3++) newMean[i3]/=wsum;
      for(var i4=0;i4<N;i4++){
        var vv=0.0;
        for(var k2=0;k2<mu;k2++){ var dd=pop[k2].u[i4]-newMean[i4]; vv+=w[k2]*dd*dd; }
        vv/=wsum;
        var sd=Math.sqrt(vv);
        var floor=0.008+0.025*Math.exp(-gen/13.0);
        var ns=0.82*Math.max(sd,floor)+0.18*sigma[i4];
        newSigma[i4]=clampv(ns,0.006,0.50);
      }
      if(stagnant>=9){
        for(var i5=0;i5<N;i5++) newSigma[i5]=Math.min(0.45,newSigma[i5]*1.35+0.01);
        if(best && best.sol && (best.sol.p||best.sol.pFast)){
          var bsrc=best.sol.p||best.sol.pFast;
          var bu=toU(bsrc,LO,HI);
          for(var i6=0;i6<N;i6++) newMean[i6]=0.8*newMean[i6]+0.2*bu[i6];
        }
        stagnant=0;
      }
      meanU=newMean; sigma=newSigma; gen++;
    }
    return best;
  }
  function bestByQuality(filter){
    var br=null,bq=-1e9;
    for(var i=0;i<allRecs.length;i++){
      var r=allRecs[i];
      if(!r || !filter(r)) continue;
      var q=r.quality;
      if(q>bq){ bq=q; br=r; }
    }
    return br;
  }
  function bestByScore(filter){
    var br=null,bs=-1e9;
    for(var i=0;i<allRecs.length;i++){
      var r=allRecs[i];
      if(!r || !filter(r)) continue;
      if(r.score>bs){ bs=r.score; br=r; }
    }
    return br;
  }

  var recPrev=evaluate(makeOld(PREV),"prevSafe");
  evaluate(makeOld(BASE),"oldBase");
  evaluate(makeOld(FAST),"fastP5");
  evaluate(makeStand(S_DEF),"standDef");
  evaluate(makeStand(S_P5),"standP5");

  var cfgSeedRun=CFG_DEF;
  var Tgrid=[6.0,7.0,7.5,8.0,8.5,9.0,9.5];
  for(var gi=0;gi<Tgrid.length;gi++){
    var cg={}; for(var ck in CFG_DEF) cg[ck]=CFG_DEF[ck]; cg.T=Tgrid[gi];
    evaluate(makeAdaptive(FAST,PREV,cg,S_P5),"adaptGrid"+gi);
  }
  var bestInitAdapt=bestByQuality(function(r){return r.sol && r.sol.mode===6;});
  if(bestInitAdapt && bestInitAdapt.sol && bestInitAdapt.sol.cfg) cfgSeedRun=bestInitAdapt.sol.cfg;

  var stableCem=cemRun(34,O_LO,O_HI,PREV,0.025,145,16,5,function(pp){return makeOld(pp);},"pureStable");
  var chosenSlow=PREV.slice();
  var safeQ=qualityRec(recPrev);
  var bestPure=bestByQuality(function(r){return r.sol && r.sol.mode===0;});
  if(bestPure && bestPure.quality>safeQ+1.0 && bestPure.sol && bestPure.sol.p){
    chosenSlow=bestPure.sol.p.slice();
    safeQ=bestPure.quality;
  }

  var cLo=[5.0,0.15,0.20,0.0,0.35,0.08,3.0,1.0,0.30,0.05,1.5,1.0,0.8,0.2,0.03,0.05,0.5,0.05,0.25,0.60,8.0,0.30];
  var cHi=[9.6,1.20,3.00,0.60,1.10,0.80,18.0,15.0,0.85,0.35,7.0,8.0,3.0,3.0,0.50,0.50,20.0,1.50,0.55,1.50,30.0,1.50];
  var cSeed=cfgToVec(cfgSeedRun);
  for(var ci=0;ci<22;ci++) cSeed[ci]=clampv(cSeed[ci],cLo[ci],cHi[ci]);
  var curFast=FAST.slice();
  var curSlow=chosenSlow.slice();
  var cfgCem=cemRun(22,cLo,cHi,cSeed,0.13,260,22,6,function(pp){return makeAdaptive(curFast,curSlow,vecToCfg(pp),S_P5);},"cfgCem");
  var curCfg=CFG_DEF;
  var bestAdapt1=bestByQuality(function(r){return r.sol && r.sol.mode===6;});
  if(bestAdapt1 && bestAdapt1.sol && bestAdapt1.sol.cfg) curCfg=bestAdapt1.sol.cfg;

  var pSeed=FAST.slice();
  if(bestAdapt1 && bestAdapt1.sol && bestAdapt1.sol.pFast) pSeed=bestAdapt1.sol.pFast.slice();
  var pCem=cemRun(34,O_LO,O_HI,pSeed,0.035,220,18,5,function(pp){return makeAdaptive(pp,curSlow,curCfg,S_P5);},"fastCem");
  var bestAdapt2=bestByQuality(function(r){return r.sol && r.sol.mode===6;});
  if(bestAdapt2 && bestAdapt2.sol && bestAdapt2.sol.pFast) curFast=bestAdapt2.sol.pFast.slice();
  if(bestAdapt2 && bestAdapt2.sol && bestAdapt2.sol.cfg) curCfg=bestAdapt2.sol.cfg;

  var cSeed2=cfgToVec(curCfg);
  for(var ci2=0;ci2<22;ci2++) cSeed2[ci2]=clampv(cSeed2[ci2],cLo[ci2],cHi[ci2]);
  var cfgCem2=cemRun(22,cLo,cHi,cSeed2,0.06,175,18,5,function(pp){return makeAdaptive(curFast,curSlow,vecToCfg(pp),S_P5);},"cfgFine");
  var bestAdapt3=bestByQuality(function(r){return r.sol && r.sol.mode===6;});
  if(bestAdapt3 && bestAdapt3.sol && bestAdapt3.sol.cfg) curCfg=bestAdapt3.sol.cfg;
  if(bestAdapt3 && bestAdapt3.sol && bestAdapt3.sol.pFast) curFast=bestAdapt3.sol.pFast.slice();

  if(evals<MAX_TRIALS-60 && !timeUp()){
    var pSeed2=curFast.slice();
    cemRun(34,O_LO,O_HI,pSeed2,0.018,95,16,5,function(pp){return makeAdaptive(pp,curSlow,curCfg,S_P5);},"fastFine");
  }

  if(evals<MAX_TRIALS-25 && !timeUp()){
    var finalTs=[7.0,7.5,8.0,8.5,9.0];
    for(var ft=0;ft<finalTs.length;ft++){
      var cc={}; for(var ck2 in CFG_DEF) cc[ck2]=CFG_DEF[ck2];
      cc.T=finalTs[ft]; cc.TD=0.45; cc.gain=1.0; cc.baseW=0.0;
      evaluate(makeAdaptive(curFast,curSlow,cc,S_P5),"finalT"+ft);
