  }
  if(evals<MAX_TRIALS && !timeUp()){
    evaluate(makeAdaptive(curFast,PREV,curCfg,S_P5),"finalCheck");
  }

  var bestAdapt=bestByQuality(function(r){return r.sol && (r.sol.mode===6||r.sol.mode===0||r.sol.mode===2);});
  var bestQ=bestAdapt?bestAdapt.quality:-1e9;
  var safePrevQ=qualityRec(recPrev);
  if(!bestAdapt || bestQ < safePrevQ+0.15) return makeOld(PREV);
  if(bestAdapt.sol && bestAdapt.sol.mode===6){
    return {mode:6,pFast:bestAdapt.sol.pFast.slice(),pSlow:bestAdapt.sol.pSlow.slice(),cfg:bestAdapt.sol.cfg,s:(bestAdapt.sol.s||S_P5).slice()};
  }
  if(bestAdapt.sol && bestAdapt.sol.mode===0 && bestAdapt.sol.p) return makeOld(bestAdapt.sol.p);
  if(bestAdapt.sol && bestAdapt.sol.mode===2 && bestAdapt.sol.p) return makeStand(bestAdapt.sol.p);
