function clampv(x,a,b){ if(!isFinite(x)) return a; if(x<a) return a; if(x>b) return b; return x; }
function num(x,d){ x=+x; return isFinite(x)?x:d; }
function wrapPM(x){ while(x>0.5)x-=1.0; while(x<-0.5)x+=1.0; return x; }

function solveIK(dx,ry,beta){
  var L=0.39,Lmax=0.7796,Lmin=0.10;
  var r2=dx*dx+ry*ry,r=Math.sqrt(r2);
  if(!(r>0.0001)){ dx=0.0; ry=0.01; r=0.01; }
  if(r>Lmax){ var sc=Lmax/r; dx*=sc; ry*=sc; r=Lmax; }
  if(r<Lmin){ var sc2=Lmin/r; dx*=sc2; ry*=sc2; r=Lmin; }
  var cosk=clampv((r*r-2.0*L*L)/(2.0*L*L),-1.0,1.0);
  var qk=-Math.acos(cosk);
  if(qk<-1.69) qk=-1.69;
  if(qk>-0.05) qk=-0.05;
  var alpha=Math.atan2(dx,ry);
  var phi1=alpha-Math.atan2(L*Math.sin(qk),L+L*Math.cos(qk));
  var qh=clampv(phi1-beta,-0.9,1.2);
  return [qh,qk];
}
function terrAt(x,a1,a2,a3,a4){
  if(x<=0.08) return 0.0;
  if(x<0.5) return Math.max(0.0,a1)*(x/0.5);
  if(x<1.0) return a1+(a2-a1)*((x-0.5)/0.5);
  if(x<2.0) return a2+(a3-a2)*(x-1.0);
  if(x<4.0) return a3+(a4-a3)*((x-2.0)/2.0);
  return a4;
}

function oldCore(obs,params,mem){
  var p=params;
  if(!p || typeof p.length!=="number" || p.length<34) p=PREV;
  obs=obs||[];
  var beta=num(obs[0],0.0), spin=num(obs[1],0.0), vx=num(obs[2],0.0), vy=num(obs[3],0.0), height=num(obs[4],1.0);
  var hipA=num(obs[5],0.0), hipAs=num(obs[6],0.0), kneeA=num(obs[7],-0.1), kneeAs=num(obs[8],0.0), footA=num(obs[9],0.0);
  var hipB=num(obs[10],0.0), hipBs=num(obs[11],0.0), kneeB=num(obs[12],-0.1), kneeBs=num(obs[13],0.0), footB=num(obs[14],0.0);
  var a1=num(obs[15],0.0), a2=num(obs[16],0.0), a3=num(obs[17],0.0), a4=num(obs[18],0.0), t=num(obs[19],0.0);
  mem=mem||{};
  var dt;
  if(!mem.init){
    mem.init=1;
    var ph0=p[23],off=p[24];
    ph0=ph0-Math.floor(ph0); off=off-Math.floor(off);
    mem.phA=ph0; mem.phB=ph0+off;
    mem.lastT=t; mem.prevA=footA; mem.prevB=footB; mem.xEst=0.0;
    dt=0.0;
  }else{
    dt=t-mem.lastT;
    if(!(dt>0.0)||dt>0.25) dt=1.0/60.0;
  }
  var freq=clampv(p[0],0.05,5.0);
  if(dt>0.0){ mem.phA+=freq*dt; mem.phB+=freq*dt; }
  if(p[22]>0.0){
    if(footA>0.5 && mem.prevA<=0.5) mem.phA+=p[22]*wrapPM(-mem.phA);
    if(footB>0.5 && mem.prevB<=0.5) mem.phB+=p[22]*wrapPM(-mem.phB);
  }
  mem.phA-=Math.floor(mem.phA); mem.phB-=Math.floor(mem.phB);
  var obsSig=Math.max(0.0,a1,a2*0.85,a3*0.55,a4*0.25);
  var slope=a2-a1;
  var hTarget=clampv(p[5]+0.40*Math.min(0.5,obsSig),0.55,1.28);
  var leanDes=clampv(p[7]+p[8]*(vx-p[6])-0.35*slope-0.15*Math.min(0.4,Math.max(0.0,a1)),-0.7,0.6);
  var uBal=p[9]*(beta-leanDes)+p[10]*spin;
  var absErr=Math.abs(beta-leanDes);
  var risk=0.0;
  if(p[27]>0.01 && absErr>p[27]) risk=Math.max(risk,(absErr-p[27])/(p[27]+0.2));
  if(p[29]>0.05 && height<p[29]) risk=Math.max(risk,(p[29]-height)/p[29]);
  if(Math.abs(spin)>2.0) risk=Math.max(risk,(Math.abs(spin)-2.0)/4.0);
  risk=clampv(risk,0.0,1.5);
  function legControl(ph,hip,hipSpd,knee,kneeSpd,foot){
    var s=ph-Math.floor(ph);
    var duty=clampv(p[1],0.25,0.95);
    var isStance=s<duty;
    var uu,shape,lift;
    if(isStance){ uu=s/duty; shape=1.0-2.0*uu; lift=0.0; }
    else{ uu=(s-duty)/(1.0-duty); shape=-Math.cos(Math.PI*uu); lift=Math.sin(Math.PI*uu); }
    var vErr=clampv(vx-p[6],-2.0,2.0);
    var A=clampv(p[2]*(1.0+p[32]*vErr),0.0,0.55);
    var base=A*shape*clampv(1.0-p[33]*risk,0.15,1.5);
