function standCore(obs,s){
  var p=s;
  if(!p || typeof p.length!=="number" || p.length<14) p=S_DEF;
  obs=obs||[];
  var beta=num(obs[0],0.0), spin=num(obs[1],0.0), vx=num(obs[2],0.0), vy=num(obs[3],0.0), height=num(obs[4],0.82);
  var hipA=num(obs[5],0.0), hipAs=num(obs[6],0.0), kneeA=num(obs[7],-0.1), kneeAs=num(obs[8],0.0);
  var hipB=num(obs[10],0.0), hipBs=num(obs[11],0.0), kneeB=num(obs[12],-0.1), kneeBs=num(obs[13],0.0);
  var a1=num(obs[15],0.0), a2=num(obs[16],0.0), a3=num(obs[17],0.0), a4=num(obs[18],0.0);
  var h0=clampv(p[0],0.50,1.10);
  var spread=clampv(p[1],0.02,0.40);
  var betaD=clampv(p[2],-0.50,0.50);
  var shift=clampv(p[3]*(beta-betaD)+p[4]*spin+p[5]*vx,-0.40,0.40);
  var hipY=h0-0.31*Math.cos(beta);
  var errH=h0-height;
  var dxA=spread+shift,dxB=-spread+shift;
  var terrA=terrAt(dxA,a1,a2,a3,a4),terrB=terrAt(dxB,a1,a2,a3,a4);
  var ryA=clampv(hipY-terrA+p[12]*errH-p[13]*vy,0.10,0.775);
  var ryB=clampv(hipY-terrB+p[12]*errH-p[13]*vy,0.10,0.775);
  var ikA=solveIK(dxA,ryA,beta),ikB=solveIK(dxB,ryB,beta);
  var uHA=p[6]*(ikA[0]-hipA)-p[7]*hipAs;
  var uHB=p[6]*(ikB[0]-hipB)-p[7]*hipBs;
  var uKA=p[8]*(ikA[1]-kneeA)-p[9]*kneeAs;
  var uKB=p[8]*(ikB[1]-kneeB)-p[9]*kneeBs;
  var bal=p[10]*(beta-betaD)+p[11]*spin;
  uHA+=bal; uHB+=bal;
  uKA+=0.5*(p[12]*errH-p[13]*vy);
  uKB+=0.5*(p[12]*errH-p[13]*vy);
  return [clampv(uHA,-1,1),clampv(uKA,-1,1),clampv(uHB,-1,1),clampv(uKB,-1,1)];
}

function hybridCore(obs,param,mem){
  var pf=param.pFast||FAST;
  var ps=param.pSlow||PREV;
  var T=clampv(num(param.T,6.0),0.0,20.0);
  var TD=clampv(num(param.TD,0.6),0.05,5.0);
  var bT=num(param.bT,0.85), bS=Math.max(0.02,num(param.bS,0.35));
  var sT=num(param.sT,11.0), sS=Math.max(0.5,num(param.sS,8.0));
  var hT=num(param.hT,0.42), hS=Math.max(0.03,num(param.hS,0.16));
  var vyT=num(param.vyT,5.0), vyS=Math.max(0.3,num(param.vyS,4.0));
  var oT=num(param.oT,0.18), oS=Math.max(0.02,num(param.oS,0.15));
  var gain=num(param.gain,1.0);
  var rate=Math.max(1.0,num(param.rate,12.0));
  mem=mem||{};
  if(!mem.hInit){
    mem.hInit=1; mem.hW=0.0; mem.hLastT=num(obs[19],0.0);
  }
  var t=num(obs[19],0.0), dt=t-mem.hLastT;
  if(!(dt>0.0)||dt>0.25) dt=1.0/60.0;
  mem.hLastT=t;
  var beta=num(obs[0],0.0), spin=num(obs[1],0.0), vy=num(obs[3],0.0), height=num(obs[4],0.8);
  var a1=num(obs[15],0.0), a2=num(obs[16],0.0), a3=num(obs[17],0.0), a4=num(obs[18],0.0);
  var obsSig=Math.max(0.0,a1,a2*0.85,a3*0.55,a4*0.25);
  var timeW=clampv((t-T)/TD,0.0,1.0);
  var risk=0.0;
  risk=Math.max(risk,(Math.abs(beta)-bT)/bS);
  risk=Math.max(risk,(Math.abs(spin)-sT)/sS);
  risk=Math.max(risk,(hT-height)/hS);
  risk=Math.max(risk,(obsSig-oT)/oS);
  if(vy < -vyT) risk=Math.max(risk,(-vy-vyT)/vyS);
  risk=clampv(risk,0.0,1.0);
  var target=Math.max(timeW,clampv(risk*gain,0.0,1.0));
  if(target>mem.hW) mem.hW=Math.min(target,mem.hW+rate*dt);
  else mem.hW=Math.max(target,mem.hW-rate*dt);
  mem.hW=clampv(mem.hW,0.0,1.0);
  var p=new Array(34);
  var w=mem.hW;
  for(var i=0;i<34;i++){
    var av=num(pf[i],PREV[i]);
    var bv=num(ps[i],PREV[i]);
    p[i]=av*(1.0-w)+bv*w;
  }
  if(!mem.hm) mem.hm={};
  return oldCore(obs,p,mem.hm);
}

function safetyPolicy(obs,out,mem){
  if(!mem) return out;
  if(!mem.sfInit){ mem.sfInit=1; mem.sfUntil=-1.0; mem.sfW=0.0; mem.sfLastT=num(obs[19],0.0); }
  var t=num(obs[19],0.0);
  var dt=t-mem.sfLastT;
  if(!(dt>0.0)||dt>0.25) dt=1.0/60.0;
  mem.sfLastT=t;
  var beta=num(obs[0],0.0),spin=num(obs[1],0.0),vy=num(obs[3],0.0),height=num(obs[4],0.8);
  var hipAs=num(obs[6],0.0),kneeAs=num(obs[8],0.0),hipBs=num(obs[11],0.0),kneeBs=num(obs[13],0.0);
  var js=Math.max(Math.abs(hipAs),Math.abs(kneeAs),Math.abs(hipBs),Math.abs(kneeBs));
  var sev=0.0;
  if(height<0.30) sev=Math.max(sev,(0.30-height)/0.10);
  if(Math.abs(beta)>1.15) sev=Math.max(sev,(Math.abs(beta)-1.15)/0.30);
  if(Math.abs(spin)>18.0) sev=Math.max(sev,(Math.abs(spin)-18.0)/8.0);
  if(vy<-7.0) sev=Math.max(sev,(-vy-7.0)/4.0);
  if(js>22.0) sev=Math.max(sev,(js-22.0)/5.0);
  if(height>1.80) sev=Math.max(sev,(height-1.80)/0.50);
  if(sev>0.0) mem.sfUntil=Math.max(mem.sfUntil,t+0.45+0.20*Math.min(sev,2.0));
  var target=(t<mem.sfUntil)?0.90:0.0;
  if(target>mem.sfW) mem.sfW=Math.min(target,mem.sfW+8.0*dt);
  else mem.sfW=Math.max(target,mem.sfW-2.0*dt);
  if(mem.sfW>0.02){
    var st=standCore(obs,S_P5),w=mem.sfW;
    return [out[0]*(1.0-w)+st[0]*w,out[1]*(1.0-w)+st[1]*w,out[2]*(1.0-w)+st[2]*w,out[3]*(1.0-w)+st[3]*w];
  }
  return out;
}

function updateMetrics(o,out){
  if(!G_REC) return;
  var beta=num(o[0],0.0),spin=num(o[1],0.0),vx=num(o[2],0.0),vy=num(o[3],0.0),height=num(o[4],0.0);
  var hipAs=num(o[6],0.0),kneeAs=num(o[8],0.0),hipBs=num(o[11],0.0),kneeBs=num(o[13],0.0),t=num(o[19],0.0);
  G_REC.calls++;
  G_REC.lastBeta=beta; G_REC.lastSpin=spin; G_REC.lastVx=vx; G_REC.lastVy=vy; G_REC.lastHeight=height; G_REC.lastT=t;
  if(height<G_REC.minH) G_REC.minH=height;
  if(height>G_REC.maxH) G_REC.maxH=height;
  if(Math.abs(beta)>G_REC.maxAbsBeta) G_REC.maxAbsBeta=Math.abs(beta);
  if(Math.abs(spin)>G_REC.maxAbsSpin) G_REC.maxAbsSpin=Math.abs(spin);
  if(Math.abs(vy)>G_REC.maxAbsVy) G_REC.maxAbsVy=Math.abs(vy);
  var js=Math.max(Math.abs(hipAs),Math.abs(kneeAs),Math.abs(hipBs),Math.abs(kneeBs));
  if(js>G_REC.maxJointSpeed) G_REC.maxJointSpeed=js;
  var fs=Math.sqrt(vx*vx+vy*vy)+0.78*Math.max(Math.abs(hipAs),Math.abs(hipBs))+0.39*Math.max(Math.abs(kneeAs),Math.abs(kneeBs));
  if(fs>G_REC.maxFootSpeed) G_REC.maxFootSpeed=fs;
  if(t>8.0){
    if(height<G_REC.minH8) G_REC.minH8=height;
    if(Math.abs(beta)>G_REC.maxAbsBeta8) G_REC.maxAbsBeta8=Math.abs(beta);
    if(Math.abs(spin)>G_REC.maxAbsSpin8) G_REC.maxAbsSpin8=Math.abs(spin);
    G_REC.sumVx8+=vx; G_REC.count8++;
  }
  if(t>9.0){
    if(height<G_REC.minH9) G_REC.minH9=height;
    if(Math.abs(beta)>G_REC.maxAbsBeta9) G_REC.maxAbsBeta9=Math.abs(beta);
    if(Math.abs(spin)>G_REC.maxAbsSpin9) G_REC.maxAbsSpin9=Math.abs(spin);
    G_REC.sumVx9+=vx; G_REC.count9++;
  }
  if(t>9.5){
    if(height<G_REC.minH95) G_REC.minH95=height;
    if(Math.abs(beta)>G_REC.maxAbsBeta95) G_REC.maxAbsBeta95=Math.abs(beta);
    if(Math.abs(spin)>G_REC.maxAbsSpin95) G_REC.maxAbsSpin95=Math.abs(spin);
    G_REC.sumVx95+=vx; G_REC.count95++;
  }
  G_REC.sumAbs+=Math.abs(out[0])+Math.abs(out[1])+Math.abs(out[2])+Math.abs(out[3]);
}

function policy(obs,params,mem){
  mem=mem||{};
  var out=null;
  if(params && typeof params.length==="number"){
    if(params.length>=34) out=oldCore(obs,params,mem);
    else if(params.length>=14) out=standCore(obs,params);
    else out=oldCore(obs,PREV,mem);
  }else if(params && typeof params==="object"){
    var mode=params.mode|0;
    if(mode===0) out=oldCore(obs,params.p||PREV,mem);
    else if(mode===2) out=standCore(obs,params.p||params.s||S_P5);
    else if(mode===8) out=hybridCore(obs,params,mem);
    else out=oldCore(obs,params.p||PREV,mem);
  }else{
    out=oldCore(obs,PREV,mem);
  }
  if(!out || out.length<4) out=[0,0,0,0];
  out=safetyPolicy(obs,out,mem);
  out=[clampv(out[0],-1,1),clampv(out[1],-1,1),clampv(out[2],-1,1),clampv(out[3],-1,1)];
  updateMetrics(obs,out);
  return out;
}

