    const mean = x0.slice();
    const sig = new Array(n).fill(sig0);
    let runBest = -Infinity, stall = 0;
    for (let g = 0; g < 200; g++) {
      if (lab.trialsLeft() <= 0 || timeUp()) return;
      const cands = [];
      for (let i = 0; i < pop; i++) {
        if (lab.trialsLeft() <= 0 || timeUp()) break;
        const x = mean.map((m, j) => clamp01(m + sig[j] * gauss()));
        const s = evalX(x);
        if (s === null) break;
        cands.push({ x: x, s: s });
      }
      if (cands.length < E) return;
      cands.sort((a, b) => b.s - a.s);
      const el = cands.slice(0, E);
      const nm = new Array(n).fill(0);
      el.forEach((e) => e.x.forEach((v, j) => { nm[j] += v / E; }));
      for (let j = 0; j < n; j++) {
        let v = 0;
        el.forEach((e) => { v += (e.x[j] - nm[j]) * (e.x[j] - nm[j]) / E; });
        sig[j] = Math.max(0.015, 0.6 * sig[j] + 0.4 * Math.sqrt(v));
        mean[j] = nm[j];
      }
      if (el[0].s > runBest + 0.02) { runBest = el[0].s; stall = 0; } else { stall++; }
      if (stall >= 6) return;
    }
  };

  let round = 0;
  while (lab.trialsLeft() > 0 && !timeUp()) {
    const r = Math.random();
    let start, sig0;
    if (round === 0 || r < 0.6) {
      start = bestX.slice(); sig0 = 0.05;
    } else if (r < 0.9) {
      const top = archive.slice().sort((a, b) => b.s - a.s).slice(0, 10);
      start = top[Math.floor(Math.random() * top.length)].x.slice(); sig0 = 0.1;
    } else {
      start = keys.map(() => Math.random()); sig0 = 0.25;
    }
    runCEM(start, sig0);
    round++;
  }

  return best || D;
}
